merge into RRL_SCHEMA_MIGRATIONS t using(select '2026-10-12-472-store-return-disposition-basis' MIGRATION_ID from dual)s on(t.MIGRATION_ID=s.MIGRATION_ID)when not matched then insert(MIGRATION_ID,DESCRIPTION,APPLIED_AT,APPLIED_BY,SCRIPT_NAME,ROLLBACK_SCRIPT,STATUS)values(s.MIGRATION_ID,'Existing store return owner: separate accepted/refused/damaged caps and exact physical unit disposition',sysdate,user,'apply.sql','rollback.sql','APPLIED');
